import React from "react";
import { useDispatch, useSelector } from "react-redux";
import { clearHistory } from "../../slices/historySlice";

const History = () => {
  const dispatch = useDispatch();
  const history = useSelector((state) => state.history.history);

  const handleClearHistory = () => {
    dispatch(clearHistory());
  };

  return (
    <div className="max-w-4xl mx-auto mt-10 p-6 bg-white rounded-lg shadow-lg">
      <h2 className="text-3xl font-semibold text-center mb-6 text-gray-800">History</h2>

      {history.length > 0 ? (
        <div className="space-y-4">
          {history.map((item, index) => (
            <div
              key={index}
              className="p-6 bg-gray-50 border rounded-lg shadow-sm hover:shadow-md transition-all duration-300"
            >
              <h3 className="text-xl font-bold text-gray-800">Prompt:</h3>
              <p className="text-gray-700 mb-2">{item.prompt}</p>

              <h3 className="text-xl font-bold text-gray-800">Response:</h3>
              <p className="text-gray-700">{item.generatedText}</p>
            </div>
          ))}
        </div>
      ) : (
        <p className="text-center text-lg text-gray-500">No history available.</p>
      )}

      <div className="flex justify-center mt-6">
        <button
          className="bg-red-500 text-white py-2 px-6 rounded-lg hover:bg-red-600 transition-colors"
          onClick={handleClearHistory}
        >
          Clear History
        </button>
      </div>
    </div>
  );
};

export default History;
